 if(pathname==='/api/backup' && method==='GET') { allow(user,'owner');return fs.readdirSync(dataDir).filter(n=>/^(backup-|auto-|before-restore-).*\.db$/.test(n)).sort().reverse(); }
 if(pathname==='/api/restore' && method==='POST') { allow(user,'owner');const name=String(required(body.name,'Backup name'));if(!/^(backup-|auto-|before-restore-)[A-Za-z0-9._-]+\.db$/.test(name))fail('Invalid backup name');const source=path.join(dataDir,name);if(!fs.existsSync(source))fail('Backup not found',404);const candidate=new DatabaseSync(source,{readOnly:true});try{if(candidate.prepare('PRAGMA integrity_check').get().integrity_check!=='ok')fail('Backup integrity check failed');candidate.prepare('SELECT id FROM users LIMIT 1').get();}finally{candidate.close();}const current=path.join(dataDir,'shop.db'),safety=path.join(dataDir,`before-restore-${Date.now()}.db`);db.exec('PRAGMA wal_checkpoint(FULL)');fs.copyFileSync(current,safety);db.close();try{fs.copyFileSync(source,current);db=new DatabaseSync(current);db.exec('PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL;');}catch(e){fs.copyFileSync(safety,current);db=new DatabaseSync(current);db.exec('PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL;');throw e;}audit({id:one('SELECT id FROM users WHERE id=?',user.id)?.id??null},'restore','backup',null,{name,safety});return {ok:true,safety}; }
