const mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.svg':'image/svg+xml','.png':'image/png'};
const server=http.createServer(async(req,res)=>{try{const url=new URL(req.url,'http://localhost');if(url.pathname.startsWith('/api/')){let raw='';for await(const chunk of req){raw+=chunk;if(raw.length>1_000_000)fail('Request too large',413);}const body=req.method==='GET'?Object.fromEntries(url.searchParams):raw?JSON.parse(raw):{};const token=(req.headers.authorization||'').replace(/^Bearer /,'');const user=token?one("SELECT u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND s.expires_at>datetime('now') AND u.active=1",token):null;return send(res,200,route(req.method,url.pathname,body,user));}let file=path.join(root,'public',url.pathname==='/'?'index.html':url.pathname);if(!file.startsWith(path.join(root,'public')+path.sep))fail('Forbidden',403);const content=fs.readFileSync(file);res.writeHead(200,{'Content-Type':mime[path.extname(file)]||'application/octet-stream','Content-Security-Policy':"default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'"});res.end(content);}catch(e){const duplicate=/UNIQUE constraint failed/.test(e.message),missing=e.code==='ENOENT';send(res,e.status||(duplicate?409:missing?404:500),{error:e.status?e.message:duplicate?'A record with this SKU, barcode or IMEI already exists':missing?'Not found':'Server error',detail:process.env.NODE_ENV==='development'?e.message:undefined});if(!e.status&&!duplicate&&!missing)console.error(e);}});
const port=Number(process.env.PORT)||3000;server.listen(port,'127.0.0.1',()=>console.log(`Mobile Shop ERP running at http://127.0.0.1:${port}`));
